37	    '[data-dc-slot].dc-dragging{transition:none;z-index:10;pointer-events:none}',
38	    '[data-dc-slot].dc-dragging .dc-card{box-shadow:0 12px 40px rgba(0,0,0,.25),0 0 0 2px #c96442;transform:scale(1.02)}',
