110	const DCCtx = React.createContext(null);
111	
112	// ─────────────────────────────────────────────────────────────
113	// DesignCanvas — stateful wrapper around the pan/zoom viewport.
114	// Owns runtime state (per-section order, renamed titles/labels, hidden
115	// artboards, focused artboard). Order/titles/labels/hidden persist to a
116	// .design-canvas.state.json
117	// sidecar next to the HTML. Reads go via plain fetch() so the saved
118	// arrangement is visible anywhere the HTML + sidecar are served together
119	// (omelette preview, direct link, downloaded zip). Writes go through the
120	// host's window.omelette bridge — editing requires the omelette runtime.
121	// Focus is ephemeral.
122	// ─────────────────────────────────────────────────────────────
123	const DC_STATE_FILE = '.design-canvas.state.json';
124	
125	function DesignCanvas({ children, minScale, maxScale, style }) {
126	  const [state, setState] = React.useState({ sections: {}, focus: null });
127	  // Hold rendering until the sidecar read settles so the saved order/titles
128	  // appear on first paint (no source-order flash). didRead gates writes until
129	  // the read settles so the empty initial state can't clobber a slow read;
130	  // skipNextWrite suppresses the one echo-write that would otherwise follow
131	  // hydration.
132	  const [ready, setReady] = React.useState(false);
133	  const didRead = React.useRef(false);
134	  const skipNextWrite = React.useRef(false);
135	
136	  React.useEffect(() => {
137	    let off = false;
138	    fetch('./' + DC_STATE_FILE)
139	      .then((r) => (r.ok ? r.json() : null))
140	      .then((saved) => {
141	        if (off || !saved || !saved.sections) return;
142	        skipNextWrite.current = true;
143	        setState((s) => ({ ...s, sections: saved.sections }));
144	      })
145	      .catch(() => {})
146	      .finally(() => { didRead.current = true; if (!off) setReady(true); });
147	    const t = setTimeout(() => { if (!off) setReady(true); }, 150);
148	    return () => { off = true; clearTimeout(t); };
149	  }, []);
150	
151	  React.useEffect(() => {
152	    if (!didRead.current) return;
153	    if (skipNextWrite.current) { skipNextWrite.current = false; return; }
154	    const t = setTimeout(() => {
155	      window.omelette?.writeFile(DC_STATE_FILE, JSON.stringify({ sections: state.sections })).catch(() => {});
156	    }, 250);
157	    return () => clearTimeout(t);
158	  }, [state.sections]);
159	
160	  // Build registries synchronously from children so FocusOverlay can read
161	  // them in the same render. Only direct DCSection > DCArtboard children are
162	  // walked — wrapping them in other elements opts out of focus/reorder.
163	  const registry = {};     // slotId -> { sectionId, artboard }
164	  const sectionMeta = {};  // sectionId -> { title, subtitle, slotIds[] }
165	  const sectionOrder = [];
166	  React.Children.forEach(children, (sec) => {
167	    if (!sec || sec.type !== DCSection) return;
168	    const sid = sec.props.id ?? sec.props.title;
169	    if (!sid) return;
170	    sectionOrder.push(sid);
171	    const persisted = state.sections[sid] || {};
172	    const abs = [];
173	    React.Children.forEach(sec.props.children, (ab) => {
174	      if (!ab || ab.type !== DCArtboard) return;
175	      const aid = ab.props.id ?? ab.props.label;
176	      if (aid) abs.push([aid, ab]);
177	    });
178	    // hidden is scoped to one source revision — when the agent regenerates
179	    // (artboard-ID set changes), prior deletes don't apply to new content.
180	    const srcKey = abs.map(([k]) => k).join('\x1f');
181	    const hidden = persisted.srcKey === srcKey ? (persisted.hidden || []) : [];
182	    const srcIds = [];
183	    abs.forEach(([aid, ab]) => {
184	      if (hidden.includes(aid)) return;
185	      registry[`${sid}/${aid}`] = { sectionId: sid, artboard: ab };
186	      srcIds.push(aid);
187	    });
188	    const kept = (persisted.order || []).filter((k) => srcIds.includes(k));
189	    sectionMeta[sid] = {
190	      title: persisted.title ?? sec.props.title,
191	      subtitle: sec.props.subtitle,
192	      slotIds: [...kept, ...srcIds.filter((k) => !kept.includes(k))],
193	    };
194	  });
195	
196	  const api = React.useMemo(() => ({
197	    state,
198	    section: (id) => state.sections[id] || {},
199	    patchSection: (id, p) => setState((s) => ({
200	      ...s,
201	      sections: { ...s.sections, [id]: { ...s.sections[id], ...(typeof p === 'function' ? p(s.sections[id] || {}) : p) } },
202	    })),
203	    setFocus: (slotId) => setState((s) => ({ ...s, focus: slotId })),
204	  }), [state]);
205	
206	  // Esc exits focus; any outside pointerdown commits an in-progress rename.
207	  React.useEffect(() => {
208	    const onKey = (e) => { if (e.key === 'Escape') api.setFocus(null); };
209	    const onPd = (e) => {
210	      const ae = document.activeElement;
211	      if (ae && ae.isContentEditable && !ae.contains(e.target)) ae.blur();
212	    };
213	    document.addEventListener('keydown', onKey);
214	    document.addEventListener('pointerdown', onPd, true);
215	    return () => {
216	      document.removeEventListener('keydown', onKey);
217	      document.removeEventListener('pointerdown', onPd, true);
218	    };
219	  }, [api]);
220	
221	  return (
222	    <DCCtx.Provider value={api}>
223	      <DCViewport minScale={minScale} maxScale={maxScale} style={style}>{ready && children}</DCViewport>
224	      {state.focus && registry[state.focus] && (
225	        <DCFocusOverlay entry={registry[state.focus]} sectionMeta={sectionMeta} sectionOrder={sectionOrder} />
226	      )}
227	    </DCCtx.Provider>
228	  );
229	}
230	
231	// ─────────────────────────────────────────────────────────────
232	// DCViewport — transform-based pan/zoom (internal)
233	//
234	// Input mapping (Figma-style):
235	//   • trackpad pinch  → zoom   (ctrlKey wheel; Safari gesture* events)
236	//   • trackpad scroll → pan    (two-finger)
237	//   • mouse wheel     → zoom   (notched; distinguished from trackpad scroll)
238	//   • middle-drag / primary-drag-on-bg → pan
239	//
240	// Transform state lives in a ref and is written straight to the DOM
241	// (translate3d + will-change) so wheel ticks don't go through React —
242	// keeps pans at 60fps on dense canvases.
243	// ─────────────────────────────────────────────────────────────
