795	  const aid = artboard.props.id ?? artboard.props.label;
796	  const idx = peers.indexOf(aid);
797	  const secIdx = sectionOrder.indexOf(sectionId);
798	
799	  const go = (d) => { const n = peers[(idx + d + peers.length) % peers.length]; if (n) ctx.setFocus(`${sectionId}/${n}`); };
800	  const goSection = (d) => {
801	    // Sections whose artboards are all deleted have slotIds:[] — step past
802	    // them to the next non-empty section so ↑/↓ doesn't dead-end.
803	    const n = sectionOrder.length;
804	    for (let i = 1; i < n; i++) {
805	      const ns = sectionOrder[(((secIdx + d * i) % n) + n) % n];
806	      const first = sectionMeta[ns] && sectionMeta[ns].slotIds[0];
807	      if (first) { ctx.setFocus(`${ns}/${first}`); return; }
808	    }
809	  };
810	
811	  React.useEffect(() => {
812	    const k = (e) => {
813	      if (e.key === 'ArrowLeft') { e.preventDefault(); go(-1); }
814	      if (e.key === 'ArrowRight') { e.preventDefault(); go(1); }
815	      if (e.key === 'ArrowUp') { e.preventDefault(); goSection(-1); }
816	      if (e.key === 'ArrowDown') { e.preventDefault(); goSection(1); }
817	    };
818	    document.addEventListener('keydown', k);
