          </div>
          <div style={{border:'1px solid '+COL.inkOnPaper, padding:'8px 12px', textAlign:'center'}}>
            <div style={{fontFamily:F.mono, fontSize:8, letterSpacing:'0.15em'}}>CEILING</div>
