  return (
    <IOSDevice dark={true} width={430} height={932}>
      <div style={{flex:1, display:'flex', flexDirection:'column', color:COL.text, overflow:'hidden'}}>
        <div style={{padding:'8px 22px 14px', borderBottom:'1px solid '+COL.line, display:'flex', justifyContent:'space-between', alignItems:'center'}}>
          <div style={{display:'flex', alignItems:'center', gap:8}}>
