// ── 5 WOW MOBILE ──────────────────────────────────────────────
function MWow() {
  const fixes = [
    {id:'hook', label:'Replace the hook', delta:18},
    {id:'cut',  label:'Trim dead air',     delta:7},
    {id:'cta',  label:'Add implicit CTA',  delta:5},
  ];
  const [a, setA] = React.useState({});
  const tgt = 62 + fixes.reduce((s,f)=>s + (a[f.id]?f.delta:0), 0);
  const [d, setD] = React.useState(62);
  React.useEffect(()=>{
    const s = d, t0 = performance.now(), dur = 700;
    let raf;
    const tick = () => {
      const p = Math.min(1, (performance.now()-t0)/dur);
      const e = 1 - Math.pow(1-p, 3);
      setD(Math.round(s + (tgt-s)*e));
      if (p<1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return ()=>cancelAnimationFrame(raf);
  }, [tgt]);

  return (
    <IOSDevice dark={true} width={430} height={932}>
      <div style={{flex:1, display:'flex', flexDirection:'column', color:COL.text, padding:'4px 22px 24px', position:'relative', overflow:'hidden'}}>
        <div style={{padding:'10px 0 14px', display:'flex', justifyContent:'space-between'}}>
          <span style={{fontFamily:F.mono, fontSize:10, color:COL.mute, letterSpacing:'0.18em'}}>← BACK</span>
          <span style={{fontFamily:F.mono, fontSize:10, color:COL.signal, letterSpacing:'0.18em'}}>WHAT IF</span>
        </div>

        <div style={{textAlign:'center', marginTop:18}}>
          <div style={{fontFamily:F.mono, fontSize:10, letterSpacing:'0.2em', color:COL.mute}}>SCORE</div>
          <div style={{
            fontFamily:F.display, fontWeight:600, fontSize:200, lineHeight:0.85, letterSpacing:'-0.05em',
            color:COL.signal,
            textShadow: `0 0 ${(d-62)*1.5}px rgba(198,255,61,${(d-62)/60})`,
            transition:'text-shadow 380ms',
          }}>{d}</div>
          <div style={{fontFamily:F.italic, fontStyle:'italic', fontSize:18, lineHeight:1.2, marginTop:8, color:COL.text, padding:'0 8px'}}>
            {d>=85?'"tier-1 video. unlocked."': d>=78?'"this posts well."': d>=70?'"real improvement. ship it."':'"apply a fix → watch it climb."'}
          </div>
        </div>

        <div style={{position:'relative', height:18, background:COL.ink2, border:'1px solid '+COL.line, marginTop:24}}>
          <div style={{position:'absolute', left:'0%', width:'14%', top:0, bottom:0, background: a.hook?'rgba(198,255,61,0.45)':'rgba(255,74,28,0.18)', borderLeft:`2px solid ${a.hook?COL.signal:COL.hot}`, borderRight:`2px solid ${a.hook?COL.signal:COL.hot}`, transition:'all 380ms cubic-bezier(.2,.8,.2,1)'}}/>
          <div style={{position:'absolute', left:'46%', width:'8%', top:0, bottom:0, background: a.cut?'rgba(198,255,61,0.45)':'rgba(255,74,28,0.18)', borderLeft:`2px solid ${a.cut?COL.signal:COL.hot}`, borderRight:`2px solid ${a.cut?COL.signal:COL.hot}`, transition:'all 380ms'}}/>
          <div style={{position:'absolute', right:'5%', width:'10%', top:0, bottom:0, background: a.cta?'rgba(198,255,61,0.45)':'rgba(255,74,28,0.18)', borderLeft:`2px solid ${a.cta?COL.signal:COL.hot}`, borderRight:`2px solid ${a.cta?COL.signal:COL.hot}`, transition:'all 380ms'}}/>
        </div>

        <div style={{marginTop:24, display:'flex', flexDirection:'column', gap:8}}>
          {fixes.map(f=>{
            const on = a[f.id];
            return (
              <button key={f.id} onClick={()=>setA(s=>({...s, [f.id]:!s[f.id]}))} style={{
                all:'unset', cursor:'pointer',
                display:'flex', alignItems:'center', gap:12,
                padding:'14px 14px',
                background: on?'rgba(198,255,61,0.08)':COL.ink2,
                border: on?'1px solid '+COL.signal:'1px solid '+COL.line,
                transition:'all 220ms',
              }}>
                <div style={{width:18, height:18, border:'1.5px solid '+COL.signal, background:on?COL.signal:'transparent', display:'flex', alignItems:'center', justifyContent:'center', fontFamily:F.mono, fontSize:11, color:COL.ink, fontWeight:700, flexShrink:0}}>{on?'✓':''}</div>
                <span style={{flex:1, fontSize:13}}>{f.label}</span>
                <span style={{fontFamily:F.display, fontWeight:600, fontSize:18, color:on?COL.signal:COL.dim}}>+{f.delta}</span>
              </button>
            );
          })}
        </div>

        <div style={{marginTop:'auto', padding:'14px 16px', border:'1px solid rgba(198,255,61,0.2)', display:'flex', justifyContent:'space-between', alignItems:'center'}}>
          <span style={{fontFamily:F.mono, fontSize:9, color:COL.mute, letterSpacing:'0.15em'}}>CEILING</span>
          <span style={{fontFamily:F.display, fontWeight:600, fontSize:28, color:COL.signal, letterSpacing:'-0.02em'}}>{62 + fixes.reduce((s,f)=>s+f.delta,0)}</span>
        </div>
      </div>
    </IOSDevice>
  );
}

// ── App ───────────────────────────────────────────────────────
function MobileApp() {
  return (
    <window.DesignCanvas title="Mobile · Lab Lime" subtitle="iPhone · 5 screens">
      <window.DCSection id="m" title="Mobile screens">
        <window.DCArtboard id="m-landing" label="01 · Landing" width={430} height={932}><MLanding/></window.DCArtboard>
        <window.DCArtboard id="m-analysis" label="02 · Analysis" width={430} height={932}><MAnalysis/></window.DCArtboard>
        <window.DCArtboard id="m-report" label="03 · Public report" width={430} height={932}><MReport/></window.DCArtboard>
        <window.DCArtboard id="m-history" label="04 · History" width={430} height={932}><MHistory/></window.DCArtboard>
        <window.DCArtboard id="m-wow" label="05 · Wow moment" width={430} height={932}><MWow/></window.DCArtboard>
      </window.DCSection>
    </window.DesignCanvas>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<MobileApp/>);

