// The wow moment — bigger, more cinematic, modern teen-feel
// Toggle fixes; the score morphs, particles fly off, the timeline heals with a wave,
// and the "tweet line" types itself in.

function WowMoment() {
  const fixes = [
    {id:'hook', label:'Replace the hook', delta:18, t:'0:00', zone:[0,14]},
    {id:'cut',  label:'Trim dead air',     delta:7,  t:'0:14', zone:[46,54]},
    {id:'cta',  label:'Add implicit CTA',  delta:5,  t:'0:22', zone:[85,95]},
  ];
  const [applied, setApplied] = React.useState({});
  const [hovering, setHovering] = React.useState(null);
  const baseScore = 62;
  const target = baseScore + fixes.reduce((s,f)=> s + (applied[f.id] ? f.delta : 0), 0);
  const previewTarget = hovering
    ? target + (applied[hovering] ? -fixes.find(f=>f.id===hovering).delta : fixes.find(f=>f.id===hovering).delta)
    : target;
  const showTarget = previewTarget;

  const [display, setDisplay] = React.useState(baseScore);
  const [pulses, setPulses] = React.useState([]);
  const lastTarget = React.useRef(target);

  React.useEffect(() => {
    const start = display;
    const t0 = performance.now();
    const dur = 900;
    let raf;
    const tick = () => {
      const p = Math.min(1, (performance.now() - t0) / dur);
      const eased = 1 - Math.pow(1 - p, 4);
      setDisplay(Math.round(start + (showTarget - start) * eased));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [showTarget]);

  // Emit particles when an actual toggle (target) changes
  React.useEffect(() => {
    if (target === lastTarget.current) return;
    const up = target > lastTarget.current;
    lastTarget.current = target;
    const id = Math.random();
    const next = Array.from({length: 14}, (_,i) => ({
      id: id + i,
      x: (Math.random()-0.5)*60,
      y: -Math.random()*200 - 60,
      r: (Math.random()-0.5)*40,
      up,
    }));
    setPulses(p => [...p, ...next]);
    setTimeout(() => setPulses(p => p.filter(x => !next.find(n => n.id === x.id))), 1200);
  }, [target]);

  const toggle = id => setApplied(a => ({...a, [id]: !a[id]}));

  const tweet = display >= 85 ? "tier-1 video. unlocked."
              : display >= 78 ? "this posts well. genuinely."
              : display >= 70 ? "real improvement. ship it."
              : display >= 65 ? "getting there. keep stacking."
              : "apply a fix → watch it climb.";

  return (
    <div style={{
      width:'100%', height:'100%',
      background:'#0E0D0B', color:'#F5F1E8',
      padding:'40px 56px',
      display:'grid', gridTemplateColumns:'380px 1fr', gap:48,
      position:'relative', overflow:'hidden',
      fontFamily:"'Geist', sans-serif",
    }}>
      {/* ambient grid */}
      <div style={{
        position:'absolute', inset:0,
        backgroundImage:'linear-gradient(rgba(198,255,61,0.04) 1px, transparent 1px), linear-gradient(90deg, rgba(198,255,61,0.04) 1px, transparent 1px)',
        backgroundSize:'88px 88px', pointerEvents:'none',
      }}/>
      {/* radial glow that intensifies with score */}
      <div style={{
        position:'absolute', inset:0, pointerEvents:'none',
        background:`radial-gradient(circle at 70% 50%, rgba(198,255,61,${0.04 + ((display-baseScore)/40)*0.18}), transparent 60%)`,
        transition:'background 600ms cubic-bezier(.2,.8,.2,1)',
      }}/>

      {/* LEFT — copy + fix toggles */}
      <div style={{position:'relative'}}>
        <div style={{fontFamily:"'JetBrains Mono', monospace", fontSize:11, letterSpacing:'0.2em', color:'#C6FF3D'}}>05 · The wow moment</div>
        <h2 style={{fontFamily:"'Clash Display', sans-serif", fontWeight:600, fontSize:50, lineHeight:0.98, letterSpacing:'-0.025em', margin:'12px 0 0'}}>
          The <em style={{fontStyle:'italic', fontFamily:"'TBJ Moder', serif", fontWeight:400}}>What If</em> dial.
        </h2>
        <p style={{fontSize:14, lineHeight:1.55, color:'#A8A092', marginTop:16, maxWidth:340}}>
          Toggle a fix. The score morphs. The timeline heals. The verdict updates in real time.
        </p>
        <p style={{fontSize:13, lineHeight:1.55, color:'#6B6557', marginTop:10, maxWidth:340, fontStyle:'italic', fontFamily:"'TBJ Moder', serif"}}>
          Hover to preview. Click to apply.
        </p>

        <div style={{marginTop:28, display:'flex', flexDirection:'column', gap:10}}>
          {fixes.map(f=>{
            const on = applied[f.id];
            return (
              <button
                key={f.id}
                onClick={()=>toggle(f.id)}
                onMouseEnter={()=>setHovering(f.id)}
                onMouseLeave={()=>setHovering(null)}
                style={{
                  all:'unset', cursor:'pointer',
                  display:'flex', alignItems:'center', gap:14,
                  padding:'16px 18px',
                  background: on ? 'rgba(198,255,61,0.08)' : '#161512',
                  border: on ? '1px solid #C6FF3D' : '1px solid rgba(255,245,210,0.1)',
                  transition:'all 280ms cubic-bezier(.2,.8,.2,1)',
                  transform: on ? 'translateX(4px)' : 'translateX(0)',
                  position:'relative', overflow:'hidden',
                }}
              >
                {/* sweep on hover */}
                <div style={{
                  position:'absolute', inset:0,
                  background:'linear-gradient(90deg, transparent, rgba(198,255,61,0.06), transparent)',
                  transform: hovering===f.id && !on ? 'translateX(100%)' : 'translateX(-100%)',
                  transition:'transform 800ms cubic-bezier(.2,.8,.2,1)',
                  pointerEvents:'none',
                }}/>
                <div style={{
                  width:22, height:22, border:'1.5px solid #C6FF3D',
                  background: on ? '#C6FF3D' : 'transparent',
                  display:'flex', alignItems:'center', justifyContent:'center',
                  fontFamily:"'JetBrains Mono', monospace", fontSize:13, color:'#0E0D0B', fontWeight:700,
                  transition:'all 220ms', flexShrink:0,
                  transform: on ? 'scale(1)' : 'scale(0.95)',
                }}>{on ? '✓' : ''}</div>
                <div style={{flex:1, position:'relative'}}>
                  <div style={{fontSize:15, color:'#F5F1E8', fontWeight: on ? 500 : 400}}>{f.label}</div>
                  <div style={{fontFamily:"'JetBrains Mono', monospace", fontSize:10, color:'#6B6557', letterSpacing:'0.1em', marginTop:2}}>at {f.t}</div>
                </div>
                <div style={{
                  fontFamily:"'Clash Display', sans-serif", fontSize:22, fontWeight:600,
                  color: on ? '#C6FF3D' : '#A8A092',
                  transition:'all 220ms',
                  position:'relative',
                }}>
                  +{f.delta}
                </div>
              </button>
            );
          })}
        </div>

        {/* mini ceiling */}
        <div style={{marginTop:24, padding:'14px 18px', border:'1px solid rgba(198,255,61,0.2)', display:'flex', justifyContent:'space-between', alignItems:'center'}}>
          <div style={{fontFamily:"'JetBrains Mono', monospace", fontSize:10, letterSpacing:'0.15em', color:'#A8A092'}}>CEILING WITH ALL FIXES</div>
          <div style={{fontFamily:"'Clash Display', sans-serif", fontWeight:600, fontSize:32, color:'#C6FF3D', letterSpacing:'-0.02em'}}>
            {baseScore + fixes.reduce((s,f)=>s+f.delta,0)}
          </div>
        </div>
      </div>

      {/* RIGHT — score readout */}
      <div style={{display:'flex', flexDirection:'column', justifyContent:'center', position:'relative'}}>

        <div style={{display:'flex', alignItems:'flex-start', gap:24, position:'relative'}}>
          {/* WAS */}
          <div style={{position:'relative'}}>
            <div style={{fontFamily:"'JetBrains Mono', monospace", fontSize:11, color:'#6B6557', letterSpacing:'0.2em'}}>WAS</div>
            <div style={{
              fontFamily:"'Clash Display', sans-serif", fontWeight:600, fontSize:104, lineHeight:0.85,
              color:'#3a3528', letterSpacing:'-0.04em',
              textDecoration:'line-through', textDecorationColor:'rgba(255,255,255,0.18)',
              textDecorationThickness:'2px',
            }}>
              {baseScore}
            </div>
          </div>

          {/* arrow */}
          <div style={{
            fontFamily:"'TBJ Moder', serif", fontStyle:'italic', fontSize:72,
            color:'#6B6557', lineHeight:1, paddingTop:38,
            transform: target > baseScore ? 'translateX(0)' : 'translateX(-4px)',
            transition:'transform 420ms cubic-bezier(.2,.8,.2,1)',
          }}>→</div>

          {/* COULD BE */}
          <div style={{position:'relative', flex:1}}>
            <div style={{fontFamily:"'JetBrains Mono', monospace", fontSize:11, color:'#C6FF3D', letterSpacing:'0.2em'}}>
              {hovering ? 'PREVIEW' : 'COULD BE'}
            </div>
            <div style={{position:'relative', display:'inline-block'}}>
              <div style={{
                fontFamily:"'Clash Display', sans-serif", fontWeight:600,
                fontSize:300, lineHeight:0.78, letterSpacing:'-0.05em',
                color:'#C6FF3D',
                fontVariantNumeric:'tabular-nums',
                textShadow: `0 0 ${Math.max(0, (display-baseScore))*1.5}px rgba(198,255,61,${(display-baseScore)/80})`,
                transition:'text-shadow 380ms',
              }}>
                {display}
              </div>
              {/* particles */}
              {pulses.map(p => (
                <div key={p.id} style={{
                  position:'absolute', top:'50%', left:'50%',
                  width:6, height:6, background: p.up ? '#C6FF3D' : '#FF4A1C',
                  borderRadius:'50%',
                  transform: `translate(${p.x}px, ${p.y}px) rotate(${p.r}deg)`,
                  opacity: 0,
                  animation: `wow-pulse 1100ms cubic-bezier(.2,.8,.2,1) forwards`,
                  animationDelay: `${Math.random()*120}ms`,
                  pointerEvents:'none',
                }} />
              ))}
            </div>
          </div>
        </div>

        {/* verdict — typewriter */}
        <div style={{
          fontFamily:"'TBJ Moder', serif", fontStyle:'italic', fontSize:34, lineHeight:1.18,
          color:'#F5F1E8', marginTop:18,
          minHeight:48,
          letterSpacing:'-0.005em',
          transition:'opacity 280ms',
        }}>
          <Typewriter text={tweet} key={tweet} />
        </div>

        {/* timeline that heals */}
        <div style={{marginTop:32}}>
          <div style={{fontFamily:"'JetBrains Mono', monospace", fontSize:10, letterSpacing:'0.15em', color:'#6B6557', marginBottom:8, display:'flex', justifyContent:'space-between'}}>
            <span>TIMELINE — HEALS AS YOU APPLY FIXES</span>
            <span>0:28 RUNTIME</span>
          </div>
          <div style={{position:'relative', height:54, background:'#161512', border:'1px solid rgba(255,245,210,0.08)'}}>
            {fixes.map(f => {
              const on = applied[f.id];
              const previewing = hovering === f.id && !on;
              const unhovering = hovering === f.id && on;
              return (
                <div key={f.id} style={{
                  position:'absolute',
                  left:`${f.zone[0]}%`,
                  width:`${f.zone[1]-f.zone[0]}%`,
                  top:0, bottom:0,
                  background: on
                    ? 'rgba(198,255,61,0.45)'
                    : previewing
                      ? 'rgba(198,255,61,0.18)'
                      : 'rgba(255,74,28,0.18)',
                  borderLeft:`2px solid ${on || previewing ? '#C6FF3D' : '#FF4A1C'}`,
                  borderRight:`2px solid ${on || previewing ? '#C6FF3D' : '#FF4A1C'}`,
                  transition:'all 380ms cubic-bezier(.2,.8,.2,1)',
                  display:'flex', alignItems:'center', justifyContent:'center',
                  fontFamily:"'JetBrains Mono', monospace", fontSize:9, letterSpacing:'0.1em',
                  color: on ? '#0E0D0B' : '#F5F1E8',
                  fontWeight: on ? 600 : 400,
                  overflow:'hidden',
                }}>
                  {on ? `+${f.delta} APPLIED` : f.t}
                </div>
              );
            })}
            {/* shimmer wave when target changes */}
            <div key={target} style={{
              position:'absolute', inset:0, pointerEvents:'none',
              background:'linear-gradient(90deg, transparent, rgba(198,255,61,0.4), transparent)',
              transform:'translateX(-100%)',
              animation:'wow-wave 900ms cubic-bezier(.2,.8,.2,1) forwards',
            }}/>
          </div>
          <div style={{display:'flex', justifyContent:'space-between', marginTop:6, fontFamily:"'JetBrains Mono', monospace", fontSize:9, color:'#6B6557', letterSpacing:'0.1em'}}>
            <span>0:00</span><span>0:07</span><span>0:14</span><span>0:21</span><span>0:28</span>
          </div>
        </div>

        {/* applied ledger */}
        <div style={{marginTop:24, display:'flex', gap:8, flexWrap:'wrap', minHeight:30}}>
          {Object.keys(applied).filter(k=>applied[k]).map(k=>{
            const f = fixes.find(x=>x.id===k);
            return (
              <div key={k} style={{
                fontFamily:"'JetBrains Mono', monospace", fontSize:10, letterSpacing:'0.1em',
                background:'rgba(198,255,61,0.1)', color:'#C6FF3D',
                border:'1px solid #C6FF3D', padding:'5px 10px',
                animation:'wow-chip 320ms cubic-bezier(.2,.8,.2,1)',
              }}>
                ✓ {f.label.toUpperCase()} · +{f.delta}
              </div>
            );
          })}
        </div>
      </div>

      <style>{`
        @keyframes wow-pulse {
          0%   { opacity: 1; transform: translate(0,0) scale(1); }
          100% { opacity: 0; transform: translate(var(--x,0), var(--y,-200px)) scale(0.4); }
        }
        @keyframes wow-pulse {
          0%   { opacity: 1; }
          100% { opacity: 0; }
        }
        @keyframes wow-wave {
          0%   { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        @keyframes wow-chip {
          0%   { opacity: 0; transform: translateY(6px) scale(0.96); }
          100% { opacity: 1; transform: translateY(0) scale(1); }
        }
      `}</style>
    </div>
  );
}

function Typewriter({text}) {
  const [n, setN] = React.useState(0);
  React.useEffect(() => {
    setN(0);
    const id = setInterval(() => {
      setN(v => {
        if (v >= text.length) { clearInterval(id); return v; }
        return v + 1;
      });
    }, 22);
    return () => clearInterval(id);
  }, [text]);
  return (
    <span>
      "{text.slice(0,n)}<span style={{opacity: n < text.length ? 1 : 0, color:'#C6FF3D'}}>▌</span>{n >= text.length ? '"' : ''}
    </span>
  );
}

window.WowMoment = WowMoment;

// iOS.jsx — Simplified iOS 26 (Liquid Glass) device frame
// Based on the iOS 26 UI Kit + Figma status bar spec. No assets, no deps.
// Exports: IOSDevice, IOSStatusBar, IOSNavBar, IOSGlassPill, IOSList, IOSListRow, IOSKeyboard

// ─────────────────────────────────────────────────────────────
// Status bar
// ─────────────────────────────────────────────────────────────
function IOSStatusBar({ dark = false, time = '9:41' }) {
  const c = dark ? '#fff' : '#000';
  return (
    <div style={{
      display: 'flex', gap: 154, alignItems: 'center', justifyContent: 'center',
      padding: '21px 24px 19px', boxSizing: 'border-box',
      position: 'relative', zIndex: 20, width: '100%',
    }}>
      <div style={{ flex: 1, height: 22, display: 'flex', alignItems: 'center', justifyContent: 'center', paddingTop: 1.5 }}>
        <span style={{
          fontFamily: '-apple-system, "SF Pro", system-ui', fontWeight: 590,
          fontSize: 17, lineHeight: '22px', color: c,
        }}>{time}</span>
      </div>
      <div style={{ flex: 1, height: 22, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 7, paddingTop: 1, paddingRight: 1 }}>
        <svg width="19" height="12" viewBox="0 0 19 12">
          <rect x="0" y="7.5" width="3.2" height="4.5" rx="0.7" fill={c}/>
          <rect x="4.8" y="5" width="3.2" height="7" rx="0.7" fill={c}/>
          <rect x="9.6" y="2.5" width="3.2" height="9.5" rx="0.7" fill={c}/>
          <rect x="14.4" y="0" width="3.2" height="12" rx="0.7" fill={c}/>
        </svg>
        <svg width="17" height="12" viewBox="0 0 17 12">
          <path d="M8.5 3.2C10.8 3.2 12.9 4.1 14.4 5.6L15.5 4.5C13.7 2.7 11.2 1.5 8.5 1.5C5.8 1.5 3.3 2.7 1.5 4.5L2.6 5.6C4.1 4.1 6.2 3.2 8.5 3.2Z" fill={c}/>
          <path d="M8.5 6.8C9.9 6.8 11.1 7.3 12 8.2L13.1 7.1C11.8 5.9 10.2 5.1 8.5 5.1C6.8 5.1 5.2 5.9 3.9 7.1L5 8.2C5.9 7.3 7.1 6.8 8.5 6.8Z" fill={c}/>
          <circle cx="8.5" cy="10.5" r="1.5" fill={c}/>
        </svg>
        <svg width="27" height="13" viewBox="0 0 27 13">
          <rect x="0.5" y="0.5" width="23" height="12" rx="3.5" stroke={c} strokeOpacity="0.35" fill="none"/>
          <rect x="2" y="2" width="20" height="9" rx="2" fill={c}/>
          <path d="M25 4.5V8.5C25.8 8.2 26.5 7.2 26.5 6.5C26.5 5.8 25.8 4.8 25 4.5Z" fill={c} fillOpacity="0.4"/>
        </svg>
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// Liquid glass pill — blur + tint + shine
// ─────────────────────────────────────────────────────────────
function IOSGlassPill({ children, dark = false, style = {} }) {
  return (
    <div style={{
      height: 44, minWidth: 44, borderRadius: 9999,
      position: 'relative', overflow: 'hidden',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      boxShadow: dark
        ? '0 2px 6px rgba(0,0,0,0.35), 0 6px 16px rgba(0,0,0,0.2)'
        : '0 1px 3px rgba(0,0,0,0.07), 0 3px 10px rgba(0,0,0,0.06)',
      ...style,
    }}>
      {/* blur + tint */}
      <div style={{
        position: 'absolute', inset: 0, borderRadius: 9999,
        backdropFilter: 'blur(12px) saturate(180%)',
        WebkitBackdropFilter: 'blur(12px) saturate(180%)',
        background: dark ? 'rgba(120,120,128,0.28)' : 'rgba(255,255,255,0.5)',
      }} />
      {/* shine */}
      <div style={{
        position: 'absolute', inset: 0, borderRadius: 9999,
        boxShadow: dark
          ? 'inset 1.5px 1.5px 1px rgba(255,255,255,0.15), inset -1px -1px 1px rgba(255,255,255,0.08)'
          : 'inset 1.5px 1.5px 1px rgba(255,255,255,0.7), inset -1px -1px 1px rgba(255,255,255,0.4)',
        border: dark ? '0.5px solid rgba(255,255,255,0.15)' : '0.5px solid rgba(0,0,0,0.06)',
      }} />
      <div style={{ position: 'relative', zIndex: 1, display: 'flex', alignItems: 'center', padding: '0 4px' }}>
        {children}
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// Navigation bar — glass pills + large title
// ─────────────────────────────────────────────────────────────
function IOSNavBar({ title = 'Title', dark = false, trailingIcon = true }) {
  const muted = dark ? 'rgba(255,255,255,0.6)' : '#404040';
  const text = dark ? '#fff' : '#000';
  const pillIcon = (content) => (
    <IOSGlassPill dark={dark}>
      <div style={{ width: 36, height: 36, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        {content}
      </div>
    </IOSGlassPill>
  );
  return (
    <div style={{
      display: 'flex', flexDirection: 'column', gap: 10,
      paddingTop: 62, paddingBottom: 10, position: 'relative', zIndex: 5,
    }}>
      <div style={{
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        padding: '0 16px',
      }}>
        {/* back chevron */}
        {pillIcon(
          <svg width="12" height="20" viewBox="0 0 12 20" fill="none" style={{ marginLeft: -1 }}>
            <path d="M10 2L2 10l8 8" stroke={muted} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
        )}
        {/* trailing ellipsis */}
        {trailingIcon && pillIcon(
          <svg width="22" height="6" viewBox="0 0 22 6">
            <circle cx="3" cy="3" r="2.5" fill={muted}/>
            <circle cx="11" cy="3" r="2.5" fill={muted}/>
            <circle cx="19" cy="3" r="2.5" fill={muted}/>
          </svg>
        )}
      </div>
      {/* large title */}
      <div style={{
        padding: '0 16px',
        fontFamily: '-apple-system, system-ui',
        fontSize: 34, fontWeight: 700, lineHeight: '41px',
        color: text, letterSpacing: 0.4,
      }}>{title}</div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// Grouped list (inset card, r:26) + row (52px)
// ─────────────────────────────────────────────────────────────
function IOSListRow({ title, detail, icon, chevron = true, isLast = false, dark = false }) {
  const text = dark ? '#fff' : '#000';
  const sec = dark ? 'rgba(235,235,245,0.6)' : 'rgba(60,60,67,0.6)';
  const ter = dark ? 'rgba(235,235,245,0.3)' : 'rgba(60,60,67,0.3)';
  const sep = dark ? 'rgba(84,84,88,0.65)' : 'rgba(60,60,67,0.12)';
  return (
    <div style={{
      display: 'flex', alignItems: 'center', minHeight: 52,
      padding: '0 16px', position: 'relative',
      fontFamily: '-apple-system, system-ui', fontSize: 17,
      letterSpacing: -0.43,
    }}>
      {icon && (
        <div style={{
          width: 30, height: 30, borderRadius: 7, background: icon,
          marginRight: 12, flexShrink: 0,
        }} />
      )}
      <div style={{ flex: 1, color: text }}>{title}</div>
      {detail && <span style={{ color: sec, marginRight: 6 }}>{detail}</span>}
      {chevron && (
        <svg width="8" height="14" viewBox="0 0 8 14" style={{ flexShrink: 0 }}>
          <path d="M1 1l6 6-6 6" stroke={ter} strokeWidth="2" fill="none" strokeLinecap="round" strokeLinejoin="round"/>
        </svg>
      )}
      {!isLast && (
        <div style={{
          position: 'absolute', bottom: 0, right: 0,
          left: icon ? 58 : 16, height: 0.5, background: sep,
        }} />
      )}
    </div>
  );
}

function IOSList({ header, children, dark = false }) {
  const hc = dark ? 'rgba(235,235,245,0.6)' : 'rgba(60,60,67,0.6)';
  const bg = dark ? '#1C1C1E' : '#fff';
  return (
    <div>
      {header && (
        <div style={{
          fontFamily: '-apple-system, system-ui', fontSize: 13,
          color: hc, textTransform: 'uppercase',
          padding: '8px 36px 6px', letterSpacing: -0.08,
        }}>{header}</div>
      )}
      <div style={{
        background: bg, borderRadius: 26,
        margin: '0 16px', overflow: 'hidden',
      }}>{children}</div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// Device frame
// ─────────────────────────────────────────────────────────────
function IOSDevice({
  children, width = 402, height = 874, dark = false,
  title, keyboard = false,
}) {
  return (
    <div style={{
      width, height, borderRadius: 48, overflow: 'hidden',
      position: 'relative', background: dark ? '#000' : '#F2F2F7',
      boxShadow: '0 40px 80px rgba(0,0,0,0.18), 0 0 0 1px rgba(0,0,0,0.12)',
      fontFamily: '-apple-system, system-ui, sans-serif',
      WebkitFontSmoothing: 'antialiased',
    }}>
      {/* dynamic island */}
      <div style={{
        position: 'absolute', top: 11, left: '50%', transform: 'translateX(-50%)',
        width: 126, height: 37, borderRadius: 24, background: '#000', zIndex: 50,
      }} />
      {/* status bar (absolute) */}
      <div style={{ position: 'absolute', top: 0, left: 0, right: 0, zIndex: 10 }}>
        <IOSStatusBar dark={dark} />
      </div>
      {/* nav + content */}
      <div style={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
        {title !== undefined && <IOSNavBar title={title} dark={dark} />}
        <div style={{ flex: 1, overflow: 'auto' }}>{children}</div>
        {keyboard && <IOSKeyboard dark={dark} />}
      </div>
      {/* home indicator — always on top */}
      <div style={{
        position: 'absolute', bottom: 0, left: 0, right: 0, zIndex: 60,
        height: 34, display: 'flex', justifyContent: 'center', alignItems: 'flex-end',
        paddingBottom: 8, pointerEvents: 'none',
      }}>
        <div style={{
          width: 139, height: 5, borderRadius: 100,
          background: dark ? 'rgba(255,255,255,0.7)' : 'rgba(0,0,0,0.25)',
        }} />
      </div>
    </div>
  );
}

// ─────────────────────────────────────────────────────────────
// Keyboard — iOS 26 liquid glass
// ─────────────────────────────────────────────────────────────
function IOSKeyboard({ dark = false }) {
  const glyph = dark ? 'rgba(255,255,255,0.7)' : '#595959';
  const sugg = dark ? 'rgba(255,255,255,0.6)' : '#333';
  const keyBg = dark ? 'rgba(255,255,255,0.22)' : 'rgba(255,255,255,0.85)';

  // special-key icons
  const icons = {
    shift: <svg width="19" height="17" viewBox="0 0 19 17"><path d="M9.5 1L1 9.5h4.5V16h8V9.5H18L9.5 1z" fill={glyph}/></svg>,
    del: <svg width="23" height="17" viewBox="0 0 23 17"><path d="M7 1h13a2 2 0 012 2v11a2 2 0 01-2 2H7l-6-7.5L7 1z" fill="none" stroke={glyph} strokeWidth="1.6" strokeLinejoin="round"/><path d="M10 5l7 7M17 5l-7 7" stroke={glyph} strokeWidth="1.6" strokeLinecap="round"/></svg>,
    ret: <svg width="20" height="14" viewBox="0 0 20 14"><path d="M18 1v6H4m0 0l4-4M4 7l4 4" fill="none" stroke="#fff" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/></svg>,
  };

  const key = (content, { w, flex, ret, fs = 25, k } = {}) => (
    <div key={k} style={{
      height: 42, borderRadius: 8.5,
      flex: flex ? 1 : undefined, width: w, minWidth: 0,
      background: ret ? '#08f' : keyBg,
      boxShadow: '0 1px 0 rgba(0,0,0,0.075)',
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      fontFamily: '-apple-system, "SF Compact", system-ui',
      fontSize: fs, fontWeight: 458, color: ret ? '#fff' : glyph,
    }}>{content}</div>
  );

  const row = (keys, pad = 0) => (
    <div style={{ display: 'flex', gap: 6.5, justifyContent: 'center', padding: `0 ${pad}px` }}>
      {keys.map(l => key(l, { flex: true, k: l }))}
    </div>
  );

  return (
    <div style={{
      position: 'relative', zIndex: 15, borderRadius: 27, overflow: 'hidden',
      padding: '11px 0 2px',
      display: 'flex', flexDirection: 'column', alignItems: 'center',
      boxShadow: dark
        ? '0 -2px 20px rgba(0,0,0,0.09)'
        : '0 -1px 6px rgba(0,0,0,0.018), 0 -3px 20px rgba(0,0,0,0.012)',
    }}>
      {/* liquid glass bg — same recipe as nav pills */}
      <div style={{
        position: 'absolute', inset: 0, borderRadius: 27,
        backdropFilter: 'blur(12px) saturate(180%)',
        WebkitBackdropFilter: 'blur(12px) saturate(180%)',
        background: dark ? 'rgba(120,120,128,0.14)' : 'rgba(255,255,255,0.25)',
      }} />
      <div style={{
        position: 'absolute', inset: 0, borderRadius: 27,
        boxShadow: dark
          ? 'inset 1.5px 1.5px 1px rgba(255,255,255,0.15)'
          : 'inset 1.5px 1.5px 1px rgba(255,255,255,0.7), inset -1px -1px 1px rgba(255,255,255,0.4)',
        border: dark ? '0.5px solid rgba(255,255,255,0.15)' : '0.5px solid rgba(0,0,0,0.06)',
        pointerEvents: 'none',
      }} />

      {/* autocorrect bar */}
      <div style={{
        display: 'flex', gap: 20, alignItems: 'center',
        padding: '8px 22px 13px', width: '100%', boxSizing: 'border-box',
        position: 'relative',
      }}>
        {['"The"', 'the', 'to'].map((w, i) => (
          <React.Fragment key={i}>
            {i > 0 && <div style={{ width: 1, height: 25, background: '#ccc', opacity: 0.3 }} />}
            <div style={{
              flex: 1, textAlign: 'center',
              fontFamily: '-apple-system, system-ui', fontSize: 17,
              color: sugg, letterSpacing: -0.43, lineHeight: '22px',
            }}>{w}</div>
          </React.Fragment>
        ))}
      </div>

      {/* key layout */}
      <div style={{
        display: 'flex', flexDirection: 'column', gap: 13,
        padding: '0 6.5px', width: '100%', boxSizing: 'border-box',
        position: 'relative',
      }}>
        {row(['q','w','e','r','t','y','u','i','o','p'])}
        {row(['a','s','d','f','g','h','j','k','l'], 20)}
        <div style={{ display: 'flex', gap: 14.25, alignItems: 'center' }}>
          {key(icons.shift, { w: 45, k: 'shift' })}
          <div style={{ display: 'flex', gap: 6.5, flex: 1 }}>
            {['z','x','c','v','b','n','m'].map(l => key(l, { flex: true, k: l }))}
          </div>
          {key(icons.del, { w: 45, k: 'del' })}
        </div>
        <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
          {key('ABC', { w: 92.25, fs: 18, k: 'abc' })}
          {key('', { flex: true, k: 'space' })}
          {key(icons.ret, { w: 92.25, ret: true, k: 'ret' })}
        </div>
      </div>

      {/* bottom spacer (emoji+mic area, icons omitted) */}
      <div style={{ height: 56, width: '100%', position: 'relative' }} />
    </div>
  );
}

Object.assign(window, {
  IOSDevice, IOSStatusBar, IOSNavBar, IOSGlassPill, IOSList, IOSListRow, IOSKeyboard,
});

// Cover — sets the tone immediately

function Cover() {
  return (
    <div style={{
      width: '100%', height: '100%',
      background: 'var(--ink)',
      color: 'var(--text)',
      padding: '72px 88px',
      position: 'relative',
      overflow: 'hidden',
      display: 'flex', flexDirection: 'column', justifyContent: 'space-between',
    }}>
      {/* faint grid */}
      <div style={{
        position:'absolute', inset:0,
        backgroundImage: 'linear-gradient(var(--line) 1px, transparent 1px), linear-gradient(90deg, var(--line) 1px, transparent 1px)',
        backgroundSize: '88px 88px',
        opacity: 0.6, pointerEvents: 'none',
      }} />

      {/* top bar */}
      <div style={{display:'flex', justifyContent:'space-between', alignItems:'center', position:'relative', fontFamily:'var(--font-mono)', fontSize:11, letterSpacing:'0.15em', textTransform:'uppercase', color:'var(--text-mute)'}}>
        <span>Design Direction · Internal</span>
        <span>FOR: Solo dev · 6-day build</span>
        <span>v1.0</span>
      </div>

      {/* center */}
      <div style={{position:'relative'}}>
        <div style={{fontFamily:'var(--font-mono)', fontSize:12, letterSpacing:'0.15em', textTransform:'uppercase', color:'var(--signal)', marginBottom:32}}>
          // The thesis, in one sentence
        </div>
        <h1 style={{
          fontFamily:'var(--font-display)', fontWeight:600, fontSize: 96,
          lineHeight: 1.02,
          letterSpacing: '-0.02em',
          margin: 0,
          maxWidth: 1180,
        }}>
          The <em style={{color:'var(--signal)', fontStyle:'italic'}}>analytical precision</em> of a Bloomberg terminal,<br/>
          dressed in the <em style={{fontStyle:'italic'}}>cultural language</em> of a creator's<br/>
          <span style={{color:'var(--text-mute)'}}>For You page.</span>
        </h1>

        <div style={{display:'flex', gap:64, marginTop:64, fontFamily:'var(--font-mono)', fontSize:12, color:'var(--text-dim)'}}>
          <Anchor n="01" name="Bloomberg Terminal" desc="Density. Mono type. The score is data, not a vibe." />
          <Anchor n="02" name="Linear" desc="Editor-dark, warm. Quiet motion. Keyboard-first feeling." />
          <Anchor n="03" name="Are.na" desc="Restraint. Treats creator work as artifacts worth indexing." />
        </div>
      </div>

      {/* bottom bar */}
      <div style={{display:'flex', justifyContent:'space-between', alignItems:'flex-end', position:'relative'}}>
        <div style={{fontFamily:'var(--font-mono)', fontSize:11, letterSpacing:'0.15em', color:'var(--text-mute)'}}>
          NOT: SaaS purple gradients · sparkle icons · undraw illustrations · "Trusted by" carousels
        </div>
        <div style={{fontFamily:'var(--font-italic)', fontStyle:'italic', fontSize:18, color:'var(--text-mute)'}}>
          → start here
        </div>
      </div>
    </div>
  );
}

function Anchor({n, name, desc}) {
  return (
    <div style={{maxWidth: 280}}>
      <div style={{color:'var(--signal)', marginBottom:8}}>{n}</div>
      <div style={{fontFamily:'var(--font-sans)', fontSize:18, color:'var(--text)', fontWeight:500, marginBottom:6}}>{name}</div>
      <div style={{lineHeight:1.55}}>{desc}</div>
    </div>
  );
}

window.Cover = Cover;

// Three names — with rationale

function Names() {
  const names = [
    {
      n: 'METRIC.fyi',
      tag: 'My pick',
      one: 'Plain. Instrumental. The .fyi makes it feel like a creator-native tool, not a SaaS.',
      detail: 'Works as a verb ("metric it"). The TLD is cheap and available. Reads like a Linear or Plausible — quiet expertise.',
      pick: true,
    },
    {
      n: 'POSTMORTEM',
      tag: 'Most distinctive',
      one: 'Brutally honest. A postmortem is what you do AFTER a video lands. Owns the harshness as a feature.',
      detail: 'Risk: maybe too dark for some creators. But it\'s memorable, ownable, and matches the editorial tone of the design.',
    },
    {
      n: 'tier1',
      tag: 'Most native',
      one: 'Creator slang. "Tier 1" = a video that pops. Names what success looks like, not what the tool does.',
      detail: 'tier1.app or tier1.video. Lowercase always. Slightly cryptic — which is on-brand for the audience.',
    },
  ];
  return (
    <div style={{
      width:'100%', height:'100%',
      background:'var(--ink)', color:'var(--text)',
      padding:'48px 64px',
      display:'flex', flexDirection:'column',
    }}>
      <div style={{display:'flex', justifyContent:'space-between', alignItems:'flex-end'}}>
        <div>
          <div style={{fontFamily:'var(--font-mono)', fontSize:11, letterSpacing:'0.2em', color:'var(--signal)'}}>06 · Naming</div>
          <h2 style={{fontFamily:'var(--font-display)', fontWeight:500, fontSize:54, lineHeight:1, letterSpacing:'-0.02em', margin:'12px 0 0'}}>
            Three names. <em style={{fontStyle:'italic', color:'var(--signal)'}}>One pick.</em>
          </h2>
        </div>
        <div style={{fontFamily:'var(--font-mono)', fontSize:11, color:'var(--text-mute)', letterSpacing:'0.1em', textAlign:'right'}}>
          .fyi / .app / .video — all available as of writing
        </div>
      </div>

      <div style={{flex:1, display:'grid', gridTemplateColumns:'1fr 1fr 1fr', gap:18, marginTop:36}}>
        {names.map((x,i)=>(
          <div key={i} style={{
            border: x.pick ? '1px solid var(--signal)' : '1px solid var(--line)',
            background: x.pick ? 'rgba(198,255,61,0.04)' : 'transparent',
            padding:'24px 24px 28px',
            display:'flex', flexDirection:'column', gap:14,
            position:'relative',
          }}>
            <div style={{display:'flex', justifyContent:'space-between', alignItems:'baseline'}}>
              <div style={{fontFamily:'var(--font-mono)', fontSize:11, color:'var(--text-mute)', letterSpacing:'0.1em'}}>0{i+1}</div>
              <div style={{fontFamily:'var(--font-mono)', fontSize:10, color: x.pick ? 'var(--signal)' : 'var(--text-mute)', letterSpacing:'0.15em', textTransform:'uppercase'}}>{x.tag}</div>
            </div>
            <div style={{fontFamily:'var(--font-display)', fontSize:64, lineHeight:0.95, letterSpacing:'-0.025em', color: x.pick ? 'var(--signal)' : 'var(--text)'}}>
              {x.n}
            </div>
            <div style={{fontFamily:'var(--font-italic)', fontStyle:'italic', fontSize:18, lineHeight:1.3, color:'var(--text)'}}>
              {x.one}
            </div>
            <div style={{fontFamily:'var(--font-sans)', fontSize:13, lineHeight:1.55, color:'var(--text-dim)'}}>
              {x.detail}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

window.Names = Names;

